        if (norm <= stop_threshold) {
            en = 0;
            *excess = (norm - start_threshold > 0.0) ? (norm - start_threshold) : 0.0;
        } else {
            en = 1;
            *excess = norm - stop_threshold;
        }
    }

    *enabled = en;

    if (en == 1) {
